function eventBoard(){const ops=engine.operations();const all=ops.reduce((n,v)=>n+(v.record?.stars||0),0);return `<div class="page events-page">${header()}<main class="event-main"><section class="event-banner"><div class="eyebrow">⚡ ARCADE CHALLENGE SYSTEM · v0.4</div><h1>EVENT<br><em>CIRCUIT.</em></h1><p>Each day brings three deterministic operations. Learn the pattern, beat your score, earn a higher medal and invest in permanent operator tools. These are real gameplay modifiers, not new policy quizzes.</p><div class="event-counter"><strong>${all} / 9</strong><small>DAILY MEDALS · ${ops[0].day} UTC</small></div></section><div class="event-info"><span>◈ THREE WORLD-SPECIFIC OPERATIONS</span><span>↻ FIXED CASES AT YOUR CURRENT TIER TODAY · REFRESHES 00:00 UTC</span></div><div class="event-grid">${ops.map((op,i)=>{const record=op.record||{best:0,stars:0,attempts:0};return `<section class="event-card event-${op.id} ${op.locked?'locked':''}" style="--event-accent:${op.accent}"><div class="event-card-top"><span class="eyebrow">OPERATION 0${i+1} / ${esc(WORLD_DEFS[op.world].title)}</span><span>${op.icon}</span></div><h2>${esc(op.title)}</h2><p class="event-sub">${esc(op.subtitle)}</p><div class="event-rule">${esc(op.rule)}<div class="event-tier">CHALLENGE TIER ${Math.min(op.level,engine.levelAccess(op.world))+1} / ${WORLD_DEFS[op.world].levels}</div></div><div class="event-achievement"><span class="event-stars">${'★'.repeat(record.stars)}${'☆'.repeat(3-record.stars)}</span><span>BEST ${fmt(record.best)} · ${record.attempts} RUNS</span></div><div class="event-reward">◈ +${fmt(op.bonus)} CREDITS PER NEW MEDAL</div><button data-cmd="start-event" data-id="${op.id}" ${op.locked?'disabled':''}>${op.locked?'UNLOCK '+WORLD_DEFS[op.world].title:'▶ START OPERATION'} ↗</button></section>`}).join('')}</div><div class="event-explain"><span>⌁ FOCUS PULSE</span><p>Correct calls fill your Pulse meter. Activate it to temporarily slow the whole operation, including arrivals and chat lifetimes. Buy permanent circuit upgrades in the Equipment Lab.</p></div><div class="event-actions"><button class="primary" data-cmd="shop">◈ UPGRADE FOCUS CIRCUIT</button><button class="secondary" data-cmd="home">↗ BACK TO WORLDS</button></div></main>${footer()}</div>`;}
